  1→/**
  2→ * PROD-002 — the application chrome: header (brand + API-mode chip), the
  3→ * primary navigation (collapsible drawer on mobile, persistent rail on
  4→ * desktop), the main landmark and the footer.
  5→ *
  6→ * A11Y: semantic landmarks (header / nav / main / footer), a skip link,
  7→ * `aria-current="page"` on the active nav link, an `aria-expanded` +
  8→ * `aria-controls` drawer toggle with ≥44px touch targets, and visible
  9→ * focus everywhere (see styles/app.css).
 10→ */
 11→
 12→import { useEffect, useState } from "react";
 13→import type { ReactNode } from "react";
 14→import { formatRoute, parseHash, type Route, type SurfaceName } from "./router";
 15→import type { ApiStatus } from "./api";
 16→
 17→/** Subscribe to the browser hash (the router's pure codec does the work). */
 18→export function useHashRoute(): Route {
 19→  const [hash, setHash] = useState(() =>
 20→    typeof window === "undefined" ? "#/" : window.location.hash || "#/",
 21→  );
 22→  useEffect(() => {
 23→    const onChange = (): void => {
 24→      setHash(window.location.hash || "#/");
 25→    };
 26→    window.addEventListener("hashchange", onChange);
 27→    return () => {
 28→      window.removeEventListener("hashchange", onChange);
 29→    };
 30→  }, []);
 31→  return parseHash(hash);
 32→}
