 75→/** The API chip: probing / live / demo (the app-level honesty badge). */
 76→function ApiChip({ status }: { readonly status: ApiStatus | null }): ReactNode {
 77→  if (status === null) {
 78→    return (
 79→      <span className="api-chip api-chip-probe" role="status">
 80→        checking API…
 81→      </span>
 82→    );
 83→  }
 84→  if (status.mode === "available") {
 85→    return (
 86→      <span className="api-chip api-chip-live" title={status.detail}>
 87→        live API
 88→      </span>
 89→    );
 90→  }
 91→  return (
 92→    <span className="api-chip api-chip-demo" title={status.detail}>
 93→      demo data — API unavailable
 94→    </span>
 95→  );
 96→}
