 98→/** The full application chrome around the routed surface. */
 99→export function AppShell({
100→  route,
101→  apiStatus,
102→  userMenu,
103→  children,
104→}: {
105→  readonly route: Route;
106→  readonly apiStatus: ApiStatus | null;
107→  /** PROD-004 (additive): the signed-in user menu; absent = pre-auth chrome. */
108→  readonly userMenu?: ReactNode;
109→  readonly children: ReactNode;
110→}): ReactNode {
111→  const [drawerOpen, setDrawerOpen] = useState(false);
112→  const activeSurface = routeSurfaceGroup(route);
113→
114→  // Close the drawer whenever the route changes (a navigation is a
115→  // completed drawer intent on mobile).
116→  useEffect(() => {
117→    setDrawerOpen(false);
118→  }, [formatRoute(route)]);
119→
120→  return (
121→    <div className="app">
122→      <a className="skip-link" href="#main-content">
123→        Skip to main content
124→      </a>
125→      <header className="app-header">
126→        <div className="app-header-inner">
127→          <a className="brand" href="#/">
128→            <span className="brand-name">AISE</span>
129→            <span className="brand-tag">AI Site Engineer — product shell</span>
130→          </a>
131→          <span className="header-spacer" />
132→          {userMenu === undefined ? null : userMenu}
133→          <ApiChip status={apiStatus} />
134→          <button
135→            type="button"
136→            className="nav-toggle"
137→            aria-expanded={drawerOpen}
138→            aria-controls="primary-nav"
139→            aria-label={drawerOpen ? "Close navigation menu" : "Open navigation menu"}
140→            onClick={() => {
141→              setDrawerOpen((open) => !open);
142→            }}
143→          >
144→            {drawerOpen ? "✕" : "☰"}
145→          </button>
146→        </div>
147→      </header>
148→      <div className="app-body">
149→        <nav
150→          className="app-nav"
151→          id="primary-nav"
152→          aria-label="Primary"
153→          data-open={drawerOpen ? "true" : "false"}
154→        >
155→          <div className="app-nav-inner">
156→            <ul className="nav-list">
157→              {PRIMARY_NAV.map((entry) => (
158→                <li key={entry.surface}>
159→                  <a
160→                    className="nav-link"
161→                    href={formatRoute(entry.target)}
162→                    aria-current={activeSurface === entry.surface ? "page" : undefined}
163→                  >
164→                    {entry.label}
165→                  </a>
166→                  {entry.subs.length === 0 ? null : (
167→                    <ul className="nav-sublist">
168→                      {entry.subs.map((sub) => (
169→                        <li key={sub.label}>
170→                          <a className="nav-link nav-sub" href={formatRoute(sub.target)}>
171→                            {sub.label}
172→                          </a>
173→                        </li>
174→                      ))}
175→                    </ul>
176→                  )}
177→                </li>
178→              ))}
179→            </ul>
180→          </div>
181→        </nav>
182→        <main className="app-main" id="main-content">
183→          {children}
184→        </main>
185→      </div>
186→      <footer className="app-footer">
187→        <div className="app-footer-inner">
188→          <span>
189→            AISE keeps observed evidence, derived interpretation and proposed
190→            interventions visually distinct. Proposed content is never presented
191→            as observed reality.
192→          </span>
193→          <span>Engineering facts remain owned by the server-side AISE records.</span>
194→        </div>
195→      </footer>
196→    </div>
