200→/** Which primary nav group a route belongs to. */
201→function routeSurfaceGroup(route: Route): SurfaceName | "projects" {
202→  switch (route.name) {
203→    case "dashboard":
204→      return "dashboard";
205→    case "projects":
206→    case "project":
207→    case "sitetwin":
208→    case "boq-lens":
209→    case "case":
210→    case "intervention":
211→    case "outcomes":
212→      return "projects";
213→    case "settings":
214→      return "settings";
215→    case "not-found":
216→      return "projects";
217→  }
218→}
