  1→/**
  2→ * AISE deployed-browser verification (PROD-012).
  3→ *
  4→ * `bun tools/deployed-check.ts` — verifies the DEPLOYED production
  5→ * deployment (default https://aise-tan.vercel.app, override with the
  6→ * AISE_DEPLOYED_URL env variable) through a REAL headless Chromium,
  7→ * mirroring the tools/smoke.ts doctrine adapted to a read-mostly remote
  8→ * target on free-tier infrastructure (docs/free-tier-deployment.md):
  9→ *
 10→ *   1. preflight: prove Chromium is installed and print the executable —
 11→ *      a missing browser FAILS EXPLICITLY with the exact install command
 12→ *      (browser checks are never silently skipped);
 13→ *   2. launches ONE Chromium (--no-sandbox: worker sandboxes lack the
 14→ *      namespace privileges the sandboxed renderer needs) and runs the
 15→ *      seven §4.3 checks SEQUENTIALLY with human-scale pacing, each in
 16→ *      its own isolated BrowserContext (the session-lifecycle semantics
 17→ *      require a pristine anonymous cookie jar):
 18→ *        availability, shell-renders, session-lifecycle,
 19→ *        responsive-desktop, responsive-mobile, accessibility,
 20→ *        console-runtime-errors;
 21→ *   3. one bounded retry per CHECK (never per assertion) for transient
 22→ *      network failures — a check that fails twice fails; which checks
 23→ *      retried is printed;
 24→ *   4. ALWAYS cleans up: the browser closes no matter what, and every
 25→ *      demo session the suite mints is logged out (the checks' own
 26→ *      finally blocks; a finally cleanup that still fails is reported
 27→ *      and fails the run);
 28→ *   5. prints `DEPLOYED: PASS` / `DEPLOYED: FAIL` and exits 0/1 — every
 29→ *      check prints one-line results with proof excerpts.
 30→ *
 31→ * The target is a verification target, NOT a load target: a single
 32→ * browser, one page at a time, bounded waits everywhere.
 33→ */
 34→
 35→import { BUDGETS, TARGET_ENV_VAR, resolveTarget } from "./deployed/config";
 36→import { chromiumExecutable, launchBrowser } from "./deployed/browser";
 37→import { ConsoleGuard } from "./deployed/console-guard";
 38→import {
 39→  checkAccessibility,
 40→  checkAvailability,
 41→  checkConsoleRuntimeErrors,
 42→  checkResponsiveDesktop,
 43→  checkResponsiveMobile,
 44→  checkSessionLifecycle,
 45→  checkShellRenders,
 46→  type CheckContext,
 47→} from "./deployed/checks";
 48→import { TransientCheckError, failedReport, type CheckReport } from "./deployed/verdict";
 49→
 50→/** One entry of the §4.3 check sequence. */
 51→interface CheckEntry {
 52→  readonly name: string;
 53→  readonly run: (ctx: CheckContext) => Promise<CheckReport>;
 54→}
 55→
 56→/** The mandated check order. */
 57→const CHECKS: readonly CheckEntry[] = [
 58→  { name: "availability", run: checkAvailability },
 59→  { name: "shell-renders", run: checkShellRenders },
 60→  { name: "session-lifecycle", run: checkSessionLifecycle },
 61→  { name: "responsive-desktop", run: checkResponsiveDesktop },
 62→  { name: "responsive-mobile", run: checkResponsiveMobile },
 63→  { name: "accessibility", run: checkAccessibility },
 64→  { name: "console-runtime-errors", run: checkConsoleRuntimeErrors },
 65→];
 66→
 67→/** A bounded sleep (never unbounded — always a §4.1 budget). */
 68→function sleep(ms: number): Promise<"slept"> {
 69→  return new Promise((resolve) => {
 70→    setTimeout(() => {
 71→      resolve("slept");
 72→    }, ms);
 73→  });
 74→}
 75→
 76→/** Reject with a TransientCheckError after the bound (never resolves). */
 77→function timeoutAfter(ms: number, what: string): Promise<never> {
 78→  return new Promise((_resolve, reject) => {
 79→    setTimeout(() => {
 80→      reject(new TransientCheckError(`${what} did not complete within ${ms} ms`, null));
 81→    }, ms);
 82→  });
 83→}
 84→
 85→/** Render an unknown error as a short string for evidence lines. */
 86→function describeError(error: unknown): string {
 87→  return error instanceof Error ? error.message : String(error);
 88→}
 89→
 90→/**
 91→ * Run one check with the ONE bounded retry (transient network failures
 92→ * only — semantic assertion failures are deterministic evidence and are
 93→ * never retried). A check that fails transiently twice FAILS.
 94→ */
 95→async function runCheckWithOneBoundedRetry(
 96→  entry: CheckEntry,
 97→  ctx: CheckContext,
 98→): Promise<{ report: CheckReport; retried: boolean }> {
 99→  try {
100→    return { report: await entry.run(ctx), retried: false };
101→  } catch (error) {
102→    if (!(error instanceof TransientCheckError)) {
103→      throw error;
104→    }
105→    console.log(
106→      `  retry: ${entry.name} — transient failure on the first attempt: ${error.message}`,
107→    );
108→    console.log(
109→      `  retry: backing off ${BUDGETS.retryBackoffMs} ms, then exactly one retry (a check that fails twice fails)`,
110→    );
111→    await sleep(BUDGETS.retryBackoffMs);
112→    try {
113→      return { report: await entry.run(ctx), retried: true };
114→    } catch (retryError) {
115→      if (retryError instanceof TransientCheckError) {
116→        return {
117→          report: failedReport(entry.name, [], [
118→            `FAIL  ${entry.name} failed transiently twice — ${retryError.message}`,
119→            `  first attempt: ${error.message}`,
120→            `  retry attempt: ${retryError.message}`,
121→          ]),
122→          retried: true,
123→        };
124→      }
125→      throw retryError;
126→    }
127→  }
128→}
129→
130→async function main(): Promise<{ pass: boolean; cleanupFailures: readonly string[] }> {
131→  console.log("AISE deployed-browser verification (PROD-012)");
132→  const target = resolveTarget(process.env[TARGET_ENV_VAR]);
133→  console.log(
134→    `target: ${target.origin} (${target.source === "env" ? `from ${TARGET_ENV_VAR}` : "the default"})`,
135→  );
136→
137→  // Preflight: a missing browser is an EXPLICIT failure, never a skip.
138→  const executable = chromiumExecutable();
139→  console.log(`chromium: ${executable}`);
140→
141→  const browser = await Promise.race([
142→    launchBrowser(),
143→    timeoutAfter(BUDGETS.gotoMs, "the Chromium launch"),
144→  ]);
145→  console.log("chromium launched (--no-sandbox, single instance, sequential checks)");
146→
147→  const guard = new ConsoleGuard();
148→  const cleanupFailures: string[] = [];
149→  const ctx: CheckContext = {
150→    browser,
151→    target,
152→    guard,
153→    noteCleanupFailure: (message) => {
154→      cleanupFailures.push(message);
155→    },
156→  };
157→
158→  const reports: CheckReport[] = [];
159→  const retriedNames: string[] = [];
160→  try {
161→    for (const entry of CHECKS) {
162→      console.log(`==> ${entry.name}`);
163→      const { report, retried } = await runCheckWithOneBoundedRetry(entry, ctx);
164→      if (retried) {
165→        retriedNames.push(entry.name);
166→      }
167→      reports.push(report);
168→      if (entry !== CHECKS[CHECKS.length - 1]) {
169→        await sleep(BUDGETS.interCheckMs);
170→      }
171→    }
172→  } finally {
173→    // ALWAYS clean up: the browser closes no matter what happened above.
174→    await browser.close();
175→    console.log("cleanup: browser closed");
176→  }
177→
178→  let pass = reports.length === CHECKS.length && reports.every((report) => report.pass);
179→  if (cleanupFailures.length > 0) {
180→    pass = false;
181→    for (const failure of cleanupFailures) {
182→      console.error(`  FAIL  cleanup — ${failure}`);
183→    }
184→  }
185→
186→  console.log("— check results —");
187→  for (const report of reports) {
188→    console.log(`  ${report.pass ? "PASS " : "FAIL "} ${report.name}`);
189→    for (const line of report.lines) {
190→      console.log(`    ${line}`);
191→    }
192→  }
193→  if (retriedNames.length > 0) {
194→    console.log(`retried (transient): ${retriedNames.join(", ")}`);
195→  }
196→
197→  return { pass, cleanupFailures };
198→}
199→
200→void (async () => {
201→  const outcome = await main().catch((error: unknown) => {
202→    console.error(`runner error: ${describeError(error)}`);
203→    return { pass: false, cleanupFailures: [] as readonly string[] };
204→  });
205→  console.log(outcome.pass ? "DEPLOYED: PASS" : "DEPLOYED: FAIL");
206→  process.exit(outcome.pass ? 0 : 1);
207→})();
208→

  1→/**
  2→ * PROD-002 — the application root: probes the same-origin API once (and on
  3→ * demand), provides the app environment (transport facts only), routes the
  4→ * hash address to ONE surface, and renders the explicit not-found surface
  5→ * for unknown addresses.
  6→ *
  7→ * While the probe is in flight the app renders a labelled loading state —
  8→ * never demo data behind a "checking" badge: the mode is resolved before
  9→ * any surface loads, and every surface's resource key includes the mode so
 10→ * a mode change re-loads honestly.
 11→ *
 12→ * PROD-004 (additive): when the API is available the app ALSO probes the
 13→ * session (`/v1/auth/whoami`). When the deployment's auth layer is active
 14→ * and no session exists, the web GATE renders (sign-in form + "Enter demo")
 15→ * BEFORE the shell instead of the surfaces; a signed-in session renders the
 16→ * shell with the user menu; a deployment without the auth layer (whoami
 17→ * 404) renders exactly the pre-auth app. ANY surface 401 re-arms the gate
 18→ * (the session died mid-flight). When the API is unavailable the app keeps
 19→ * its honest demo-dataset behavior — the gate never blocks the offline
 20→ * fallback.
 21→ */
 22→
 23→import { useCallback, useEffect, useMemo, useReducer, useState } from "react";
 24→import type { ReactNode } from "react";
 25→import { probeApi, type ApiStatus } from "./api";
 26→import { enterDemoSession, probeAuth, signInPrincipal, signOutSession } from "./api";
 27→import { AppEnvironmentContext, type AppEnvironment } from "./environment";
 28→import { AppShell, useHashRoute } from "./AppShell";
 29→import { AuthGate, UserMenu, type GateActions } from "./AuthGate";
 30→import { formatRoute, routeKey, type Route } from "./router";
 31→import { gateAdmitsSurfaces, gateReducer, initialGateState } from "./gate";
 32→import { LoadingPanel } from "./components";
 33→import { Dashboard } from "./surfaces/Dashboard";
 34→import { Projects } from "./surfaces/Projects";
 35→import { ProjectOverview } from "./surfaces/ProjectOverview";
 36→import { SiteTwin } from "./surfaces/SiteTwin";
 37→import { BoqLensSurface } from "./surfaces/BoqLens";
 38→import { EngineeringCase } from "./surfaces/EngineeringCase";
 39→import { InterventionStudio } from "./surfaces/InterventionStudio";
 40→import { Outcomes } from "./surfaces/Outcomes";
 41→import { Settings } from "./surfaces/Settings";
 42→
 43→/** The browser's fetch (same-origin paths only — see api.ts). */
 44→const browserFetch = (input: string, init?: RequestInit): Promise<Response> =>
 45→  fetch(input, init);
 46→
 47→/** The product application. */
 48→export function App(): ReactNode {
 49→  const [apiStatus, setApiStatus] = useState<ApiStatus | null>(null);
 50→  const [probeAttempt, setProbeAttempt] = useState(1);
 51→  const [principalId, setPrincipalId] = useState("user-alice");
 52→
 53→  // PROD-010: the ACTING PRINCIPAL the session was minted for. The whoami
 54→  // probe is display-only by design (AISE-036), so the app REMEMBERS the id
 55→  // it authenticated with — typed at sign-in, the documented demo default
 56→  // ("demo-evaluator") on Enter-demo — session-scoped so a reload keeps it
 57→  // while the session lives. The SERVER stays the authority: a mismatched
 58→  // or expired session surfaces as the honest typed 401/403 (never a
 59→  // silently-wrong identity).
 60→  const [sessionPrincipalId, setSessionPrincipalId] = useState<string | null>(() => {
 61→    try {
 62→      return sessionStorage.getItem("aise.acting-principal");
 63→    } catch {
 64→      return null;
 65→    }
 66→  });
 67→  const rememberActingPrincipal = useCallback((id: string) => {
 68→    setSessionPrincipalId(id);
 69→    try {
 70→      sessionStorage.setItem("aise.acting-principal", id);
 71→    } catch {
 72→      // storage unavailable — the in-memory state stands for this page
 73→    }
 74→  }, []);
 75→  const forgetActingPrincipal = useCallback(() => {
 76→    setSessionPrincipalId(null);
 77→    try {
 78→      sessionStorage.removeItem("aise.acting-principal");
 79→    } catch {
 80→      // storage unavailable — the in-memory state is already cleared
 81→    }
 82→  }, []);
 83→  const [gate, dispatch] = useReducer(gateReducer, undefined, initialGateState);
 84→
 85→  useEffect(() => {
 86→    let cancelled = false;
 87→    void probeApi(browserFetch).then((status) => {
 88→      if (!cancelled) {
 89→        setApiStatus(status);
 90→      }
 91→    });
 92→    return () => {
 93→      cancelled = true;
 94→    };
 95→  }, [probeAttempt]);
 96→
 97→  const reprobe = useCallback(() => {
 98→    setApiStatus(null);
 99→    setProbeAttempt((attempt) => attempt + 1);
100→  }, []);
101→
102→  // PROD-004: probe the session ONLY when the API is available (an
103→  // unavailable API keeps the honest demo-dataset fallback — no gate).
104→  // The reducer ignores late answers after a retry (deterministic machine).
105→  const apiAvailable = apiStatus !== null && apiStatus.mode === "available";
106→  useEffect(() => {
107→    if (!apiAvailable || gate.status !== "probing") {
108→      return;
109→    }
110→    let cancelled = false;
111→    void probeAuth(browserFetch).then((probe) => {
112→      if (!cancelled) {
113→        dispatch({ type: "probe-settled", probe });
114→      }
115→    });
116→    return () => {
117→      cancelled = true;
118→    };
119→  }, [apiAvailable, gate.status]);
120→
121→  // The environment's transport: the browser fetch WRAPPED so any surface
122→  // 401 re-arms the gate (the auth-aware seam — api.ts's isUnauthorized is
123→  // the typed signal; here it is wired to the state machine). The request
124→  // runs ONCE; only the response is observed.
125→  const gatedFetch = useCallback(
126→    (input: string, init?: RequestInit): Promise<Response> => {
127→      return browserFetch(input, init).then((response) => {
128→        if (response.status === 401) {
129→          dispatch({ type: "unauthorized" });
130→        }
131→        return response;
132→      });
133→    },
134→    [],
135→  );
136→
137→  // PROD-010: the ACTING PRINCIPAL follows the authenticated session —
138→  // the remembered session principal when one exists; the demo default
139→  // (user-alice, the Settings selection) stands only when there is no
140→  // session (demo mode / auth-inactive).
141→  const actingPrincipalId = sessionPrincipalId ?? principalId;
142→
143→  const environment = useMemo<AppEnvironment>(
144→    () => ({ apiStatus, fetchImpl: apiAvailable ? gatedFetch : browserFetch, principalId: actingPrincipalId }),
145→    [apiStatus, apiAvailable, actingPrincipalId, gatedFetch],
146→  );
147→
148→  const route = useHashRoute();
149→
150→  // The gate's intents (async results land as typed events — the components
151→  // stay pure projections).
152→  const gateActions = useMemo<GateActions>(
153→    () => ({
154→      onSignIn: (id: string) => {
155→        dispatch({ type: "sign-in-submitted" });
156→        void signInPrincipal(browserFetch, id).then((result) => {
157→          if (result.ok) {
158→            rememberActingPrincipal(id);
159→          }
160→          dispatch(
161→            result.ok
162→              ? { type: "action-succeeded", principal: result.principal }
163→              : { type: "action-failed", failure: result.failure },
164→          );
165→        });
166→      },
167→      onEnterDemo: () => {
168→        dispatch({ type: "demo-submitted" });
169→        void enterDemoSession(browserFetch).then((result) => {
170→          // The documented demo principal (the server's AISE_DEMO_PRINCIPAL
171→          // default — a deployment overriding it gets the honest typed 403
172→          // on guarded reads, never a silently-wrong identity).
173→          if (result.ok) {
174→            rememberActingPrincipal("demo-evaluator");
175→          }
176→          dispatch(
177→            result.ok
178→              ? { type: "action-succeeded", principal: result.principal }
179→              : { type: "action-failed", failure: result.failure },
180→          );
181→        });
182→      },
183→      onRetry: () => {
184→        dispatch({ type: "retry-probe" });
185→      },
186→    }),
187→    [rememberActingPrincipal],
188→  );
189→
190→  const signOut = useCallback(() => {
191→    dispatch({ type: "sign-out-submitted" });
192→    void signOutSession(browserFetch).then((result) => {
193→      if (result.ok) {
194→        forgetActingPrincipal();
195→      }
196→      dispatch(
197→        result.ok
198→          ? { type: "action-succeeded", principal: null }
199→          : { type: "action-failed", failure: result.failure },
200→      );
201→    });
202→  }, [forgetActingPrincipal]);
203→
204→  // The gate renders INSTEAD of the shell only when the auth layer is
205→  // active and blocking (signed-out / probe-error). Every other state is
206→  // the additive pass-through.
207→  const gateBlocks = apiAvailable && !gateAdmitsSurfaces(gate);
208→  const userMenu =
209→    gate.status === "signed-in" && gate.principal !== null ? (
210→      <UserMenu
211→        principal={gate.principal}
212→        signingOut={gate.submitting === "sign-out"}
213→        onSignOut={signOut}
214→      />
215→    ) : null;
216→
217→  return (
218→    <AppEnvironmentContext.Provider value={environment}>
219→      {gateBlocks ? (
220→        <AuthGate state={gate} actions={gateActions} />
221→      ) : (
222→        <AppShell route={route} apiStatus={apiStatus} userMenu={userMenu}>
223→          {apiStatus === null ? (
224→            <LoadingPanel label="Checking the API on this origin…" />
225→          ) : apiAvailable && gate.status === "probing" ? (
226→            <LoadingPanel label="Checking your session on this origin…" />
227→          ) : (
228→            <RoutedSurface
229→              route={route}
230→              principalId={actingPrincipalId}
231→              onPrincipalChange={setPrincipalId}
232→              onReprobe={reprobe}
233→            />
234→          )}
235→        </AppShell>
236→      )}
237→    </AppEnvironmentContext.Provider>
238→  );
239→}
240→
241→/** Render the surface one route addresses (the typed switch). */
242→function RoutedSurface({
243→  route,
244→  principalId,
245→  onPrincipalChange,
246→  onReprobe,
247→}: {
248→  readonly route: Route;
249→  readonly principalId: string;
250→  readonly onPrincipalChange: (principalId: string) => void;
251→  readonly onReprobe: () => void;
252→}): ReactNode {
253→  switch (route.name) {
254→    case "dashboard":
255→      return <Dashboard />;
256→    case "projects":
257→      return <Projects />;
258→    case "project":
259→      return <ProjectOverview projectId={route.projectId} />;
260→    case "sitetwin":
261→      return <SiteTwin projectId={route.projectId} />;
262→    case "boq-lens":
263→      return <BoqLensSurface projectId={route.projectId} />;
264→    case "case":
265→      return <EngineeringCase projectId={route.projectId} />;
266→    case "intervention":
267→      return (
268→        <InterventionStudio
269→          key={routeKey(route)}
270→          projectId={route.projectId}
271→          layer={route.query.layer ?? 0}
272→          scenarioId={route.query.scenario}
273→        />
274→      );
275→    case "outcomes":
276→      return <Outcomes projectId={route.projectId} />;
277→    case "settings":
278→      return (
279→        <Settings
280→          principalId={principalId}
281→          onPrincipalChange={onPrincipalChange}
282→          onReprobe={onReprobe}
283→        />
284→      );
285→    case "not-found":
286→      return <NotFound hash={route.hash} />;
287→  }
288→}
289→
290→/** The explicit not-found surface: the offending address + honest guidance. */
291→export function NotFound({ hash }: { readonly hash: string }): ReactNode {
292→  return (
293→    <section className="card" aria-labelledby="not-found-title">
294→      <div className="card-head">
295→        <h2 id="not-found-title" className="card-title">
296→          This address does not match any product surface
297→        </h2>
298→      </div>
299→      <div className="card-body">
300→        <p>
301→          The address <code className="mono">{hash}</code> is not one of the
302→          product&apos;s routes. Nothing was guessed and no fallback surface
303→          was rendered.
304→        </p>
305→        <p>The product surfaces are:</p>
306→        <ul className="notes-list">
307→          <li>
308→            <a href={formatRoute({ name: "dashboard" })}>Dashboard</a> — the landing overview
309→          </li>
310→          <li>
311→            <a href={formatRoute({ name: "projects" })}>Projects</a> — open a project
312→          </li>
313→          <li>
314→            <a href={formatRoute({ name: "sitetwin", projectId: "proj-riverside-refit" })}>
315→              SiteTwin / Evidence
316→            </a>{" "}
317→            — synchronized 2D/3D + evidence (per project)
318→          </li>
319→          <li>
320→            <a href={formatRoute({ name: "boq-lens", projectId: "proj-riverside-refit" })}>
321→              BOQ Lens
322→            </a>{" "}
323→            — verbatim BOQ scope + mapping (per project)
324→          </li>
325→          <li>
326→            <a href={formatRoute({ name: "case", projectId: "proj-riverside-refit" })}>
327→              Engineering Case
328→            </a>{" "}
329→            — observations / hypotheses / missing evidence (per project)
330→          </li>
331→          <li>
332→            <a
333→              href={formatRoute({
334→                name: "intervention",
