781→/** Count axe violations by impact level. */
782→function countByImpact(
783→  violations: readonly { readonly impact?: string | null }[],
784→): { critical: number; serious: number; moderate: number; minor: number; none: number } {
785→  const counts = { critical: 0, serious: 0, moderate: 0, minor: 0, none: 0 };
786→  for (const violation of violations) {
787→    switch (violation.impact) {
788→      case "critical":
789→        counts.critical += 1;
790→        break;
791→      case "serious":
792→        counts.serious += 1;
793→        break;
794→      case "moderate":
795→        counts.moderate += 1;
796→        break;
797→      case "minor":
798→        counts.minor += 1;
799→        break;
800→      default:
801→        counts.none += 1;
802→        break;
803→    }
804→  }
805→  return counts;
806→}
