    // menu + api chip must sit on the SAME row. The drawer toggle is
    // display:none BY DESIGN at >=880px (`.app-header-inner .nav-toggle`);
    // it is reported for honesty and only joins the one-row set if it is
    // somehow visible (which would itself be a regression to investigate).
    const row = await page.evaluate(() => {
      const required = [".brand", ".user-menu", ".api-chip"];
      const tops: { label: string; top: number; visible: boolean }[] = [];
      for (const selector of [...required, ".nav-toggle"]) {
        const el = document.querySelector(selector);
        if (el === null) {
          tops.push({ label: selector, top: Number.NaN, visible: false });
          continue;
        }
        const style = getComputedStyle(el);
        const rendered = style.display !== "none";
        const rect = el.getBoundingClientRect();
        tops.push({
          label: selector,
          top: rect.top,
          visible: rendered && rect.width > 0 && rect.height > 0,
